use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl < 'a > LabelText < 'a > { pub fn label < S : Into < Cow < 'a , str > > > (s : S) -> LabelText < 'a > { LabelStr (s . into ()) } pub fn html < S : Into < Cow < 'a , str > > > (s : S) -> LabelText < 'a > { HtmlStr (s . into ()) } fn escape_char < F > (c : char , mut f : F) where F : FnMut (char) , { match c { '\\' => f (c) , _ => { for c in c . escape_default () { f (c) } } } } fn escape_str (s : & str) -> String { let mut out = String :: with_capacity (s . len ()) ; for c in s . chars () { LabelText :: escape_char (c , | c | out . push (c)) ; } out } # [doc = " Renders text as string suitable for a label in a .dot file."] # [doc = " This includes quotes or suitable delimiters."] pub fn to_dot_string (& self) -> String { match * self { LabelStr (ref s) => format ! ("\"{}\"" , s . escape_default ()) , EscStr (ref s) => format ! ("\"{}\"" , LabelText :: escape_str (s)) , HtmlStr (ref s) => format ! ("<{s}>") , } } }